#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int capacity, q;
    cin >> capacity >> q;
    list<int> order;
    unordered_map<int, pair<int, list<int>::iterator>> cache;

    while (q--) {
        string op;
        int key;
        cin >> op >> key;
        if (op == "GET") {
            auto it = cache.find(key);
            if (it == cache.end()) {
                cout << -1 << '\n';
                continue;
            }
            int value = it->second.first;
            order.erase(it->second.second);
            order.push_front(key);
            it->second.second = order.begin();
            cout << value << '\n';
        } else {
            int value;
            cin >> value;
            auto it = cache.find(key);
            if (it != cache.end()) {
                order.erase(it->second.second);
                order.push_front(key);
                it->second = {value, order.begin()};
                continue;
            }
            if ((int)cache.size() == capacity) {
                int victim = order.back();
                order.pop_back();
                cache.erase(victim);
            }
            order.push_front(key);
            cache[key] = {value, order.begin()};
        }
    }
    return 0;
}

