#include <bits/stdc++.h>
using namespace std;

uint32_t parseIp(const string& text) {
    string part;
    stringstream ss(text);
    uint32_t value = 0;
    for (int i = 0; i < 4; ++i) {
        getline(ss, part, '.');
        value = (value << 8) | static_cast<uint32_t>(stoul(part));
    }
    return value;
}

uint32_t prefixMask(int length) {
    if (length == 0) return 0;
    return 0xffffffffu << (32 - length);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    struct Route {
        uint32_t network;
        int length;
        string nextHop;
    };
    vector<Route> routes;
    for (int i = 0; i < n; ++i) {
        string prefix, nextHop;
        cin >> prefix >> nextHop;
        size_t slash = prefix.find('/');
        uint32_t ip = parseIp(prefix.substr(0, slash));
        int length = stoi(prefix.substr(slash + 1));
        uint32_t mask = prefixMask(length);
        routes.push_back({ip & mask, length, nextHop});
    }

    while (q--) {
        string text;
        cin >> text;
        uint32_t ip = parseIp(text);
        int bestLength = -1;
        string answer = "NONE";
        for (const auto& route : routes) {
            uint32_t mask = prefixMask(route.length);
            if ((ip & mask) == route.network && route.length > bestLength) {
                bestLength = route.length;
                answer = route.nextHop;
            }
        }
        cout << answer << '\n';
    }
    return 0;
}

