#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    struct Task {
        int id;
        long long arrival;
        long long duration;
        int priority;
        bool done;
    };
    vector<Task> tasks(n);
    for (auto& task : tasks) {
        cin >> task.id >> task.arrival >> task.duration >> task.priority;
        task.done = false;
    }

    long long now = 0;
    for (int finished = 0; finished < n; ++finished) {
        int best = -1;
        for (int i = 0; i < n; ++i) {
            if (tasks[i].done || tasks[i].arrival > now) continue;
            if (best == -1 ||
                tasks[i].priority > tasks[best].priority ||
                (tasks[i].priority == tasks[best].priority && tasks[i].arrival < tasks[best].arrival) ||
                (tasks[i].priority == tasks[best].priority && tasks[i].arrival == tasks[best].arrival &&
                 tasks[i].id < tasks[best].id)) {
                best = i;
            }
        }
        if (best == -1) {
            long long nextArrival = LLONG_MAX;
            for (const auto& task : tasks) {
                if (!task.done) nextArrival = min(nextArrival, task.arrival);
            }
            now = nextArrival;
            --finished;
            continue;
        }
        if (finished) cout << ' ';
        cout << tasks[best].id;
        now += tasks[best].duration;
        tasks[best].done = true;
    }
    cout << '\n';
    return 0;
}

