#include <bits/stdc++.h>
using namespace std;

class Parser {
public:
    explicit Parser(string input) : text(move(input)), pos(0) {}

    long long parseExpression() {
        long long value = parseTerm();
        while (true) {
            skipSpaces();
            if (match('+')) value += parseTerm();
            else if (match('-')) value -= parseTerm();
            else break;
        }
        return value;
    }

private:
    string text;
    size_t pos;

    void skipSpaces() {
        while (pos < text.size() && isspace(static_cast<unsigned char>(text[pos]))) ++pos;
    }

    bool match(char ch) {
        skipSpaces();
        if (pos < text.size() && text[pos] == ch) {
            ++pos;
            return true;
        }
        return false;
    }

    long long parseTerm() {
        long long value = parseFactor();
        while (true) {
            skipSpaces();
            if (match('*')) value *= parseFactor();
            else if (match('/')) value /= parseFactor();
            else break;
        }
        return value;
    }

    long long parseFactor() {
        skipSpaces();
        if (match('+')) return parseFactor();
        if (match('-')) return -parseFactor();
        if (match('(')) {
            long long value = parseExpression();
            match(')');
            return value;
        }
        long long value = 0;
        while (pos < text.size() && isdigit(static_cast<unsigned char>(text[pos]))) {
            value = value * 10 + (text[pos++] - '0');
        }
        return value;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string expression;
    getline(cin, expression);
    cout << Parser(expression).parseExpression() << '\n';
    return 0;
}
